contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address spender, uint256 v1, uint256 v2) public {
        require(spender != address(0));
        require(v1 != 0);
        require(v2 != 0);
        require(v2 != v1);

        bool ok1 = c.approve(spender, v1); if (__ESBMC_reverted()) return;
        uint256 a1 = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        bool ok2 = c.approve(spender, v2); if (__ESBMC_reverted()) return;
        uint256 a2 = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        bool ok3 = c.approve(spender, 0); if (__ESBMC_reverted()) return;
        uint256 a3 = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        assert(ok1 && !ok2 && a1 == v1 && a2 == v1 && ok3 && a3 == 0);
    }

    receive() external payable {}
}

